def solve(x):
    visited = set()
    stack = [x["start"]]
    result = set()

    while stack:
        node = stack.pop()
        if node in visited:
            continue
        visited.add(node)
        result.add(node)
        for neighbor in [b for a, b in x["edges"] if a == node]:
            stack.append(neighbor)

    return sorted(result)
